using System;
using System.IO;
using System.Linq;
using Siderectomy;
using UnityEngine;
public static class DemoSaveChecks {
 static void Check(bool condition,string reason){if(!condition)throw new Exception("SAVE_CHECK: "+reason);}
 static bool Equivalent(object a,object b){if(a==null||b==null)return a==b;if(a.GetType()!=b.GetType())return false;if(a is double)return Math.Abs((double)a-(double)b)<1e-7;if(a is string||a.GetType().IsPrimitive)return a.Equals(b);if(a is System.Collections.IEnumerable){var x=((System.Collections.IEnumerable)a).Cast<object>().ToArray();var y=((System.Collections.IEnumerable)b).Cast<object>().ToArray();return x.Length==y.Length&&x.Zip(y,Equivalent).All(v=>v);}return a.GetType().GetFields(System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.Instance).All(f=>Equivalent(f.GetValue(a),f.GetValue(b)));}
 public static void Run(){string previous=DemoSaveStore.TestDirectory;var profile=DemoSession.Profile;DemoSaveStore.TestDirectory=Path.GetFullPath("Temp/SaveChecks_"+Guid.NewGuid().ToString("N"));
  try{var rules=DemoRuleBook.Load();var s=new DemoSimulation(DemoLevel.Defaults()[3],rules);s.GlobalProbe=true;s.Body.recon=true;s.Res[0]=1000;s.Res[1]=1000;s.Res[2]=1000;s.Res[3]=1000;s.Carriers["dust"]=3;s.Submit("facility","energy");s.Submit("research","stealth");s.Submit("apply","apply");s.PrepareAttackModule("surface");s.Launch("surface","dust");s.Paused=false;s.Advance(3);s.Paused=true;s.Body.nodes[0].hp-=17;s.Research["calibration"]=1.15;s.Viruses.Add(new DemoVirus{body=s.Selected,next=s.Time+2,strength=.2,count=2});s.Ships.Add(new DemoShip{id=999,body=s.Selected,pop=8,left=35,total=60});s.SelectedShip=999;
   var snapshot=s.Capture();var p=DemoSaveStore.Create("持久化边界验收");p.currentLevel=4;p.highestUnlockedLevel=4;p.hasCheckpoint=true;p.checkpoint=snapshot;DemoSaveStore.Save(p);string json=JsonUtility.ToJson(s.Capture());var loaded=DemoSaveStore.Load(p.id);var restored=DemoSimulation.Restore(loaded.checkpoint,rules);Check(JsonUtility.ToJson(restored.Capture())==json,"全部模拟状态往返一致（含随机种子、序列号、损伤和队列）");restored.Paused=false;s.Paused=false;s.Advance(40);restored.Advance(40);Directory.CreateDirectory("Temp/SaveDiff");File.WriteAllText("Temp/SaveDiff/original.json",JsonUtility.ToJson(s.Capture(),true));File.WriteAllText("Temp/SaveDiff/restored.json",JsonUtility.ToJson(restored.Capture(),true));Check(Equivalent(s.Capture(),restored.Capture()),"读档后结算与未中断模拟一致");
   Check(loaded.checkpoint.Time==snapshot.Time,"恢复不会修改原始快照");var other=DemoSaveStore.Create("独立存档");Check(!DemoSaveStore.Load(other.id).hasCheckpoint,"新档案不携带另一档案进度");Check(DemoSaveStore.HasBackup(p.id),"覆盖保存生成备份");string path=Path.Combine(DemoSaveStore.DirectoryPath,"slot_"+p.id+".json");File.WriteAllText(path,"damaged");bool refused=false;try{DemoSaveStore.Load(p.id);}catch{refused=true;}Check(refused&&DemoSaveStore.List().Any(e=>e.id==p.id&&e.error!=null),"损坏存档拒绝载入且仍可管理");Check(DemoSaveStore.LoadBackup(p.id).id==p.id,"损坏后可读取上一份备份");DemoSaveStore.Delete(p.id);Check(!File.Exists(path)&&!File.Exists(path+".bak")&&DemoSaveStore.Load(other.id).id==other.id,"删档同时删除备份且不影响其他档案");
   var empty=new DemoSimulation(DemoLevel.Defaults()[0],rules);var emptyRestored=DemoSimulation.Restore(empty.Capture(),rules);empty.Paused=emptyRestored.Paused=false;empty.Advance(2);emptyRestored.Advance(2);Check(JsonUtility.ToJson(empty.Capture())==JsonUtility.ToJson(emptyRestored.Capture()),"无AI队列及空集合往返有效");
   Directory.CreateDirectory("Docs/Validation/LayoutSave");File.WriteAllText("Docs/Validation/LayoutSave/存档规则验收.txt","PASS 新建、独立档案、全部模拟字段往返、随机状态与40秒后续结算一致、空队列、备份、损坏识别、读取备份、删档隔离。\n");Debug.Log("SAVE_CHECKS_OK");
  }finally{DemoSaveStore.TestDirectory=previous;DemoSession.Profile=profile;}
 }
 public static void ValidateAndBuild(){DemoInformationChecks.Run();Run();DemoHudChecks.Run();DemoBuilder.ValidateAndBuildWindows();}
}
